<label class="patient-field"><span>{{ __('patients.full_name') }}</span><input name="full_name" value="{{ old('_form') === ($contactForm ?? 'new-patient') ? old('full_name') : ($patient->full_name ?? '') }}" maxlength="120" required autocomplete="name"></label>
<label class="patient-field"><span>{{ __('patients.phone') }}</span><input name="phone" type="tel" value="{{ old('_form') === ($contactForm ?? 'new-patient') ? old('phone') : ($patient->phone ?? '') }}" maxlength="30" required autocomplete="tel" dir="ltr"></label>
<label class="patient-field"><span>{{ __('patients.email') }}</span><input name="email" type="email" value="{{ old('_form') === ($contactForm ?? 'new-patient') ? old('email') : ($patient->email ?? '') }}" maxlength="255" autocomplete="email" dir="ltr"></label>
